#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<long long> b;
    long long otv = 0;

    int limit1 = 1 << (n / 2 + n % 2);
    for (int i = 0; i < limit1; ++i) {
        long long t = 0;
        int k = i;
        for (int j = 0; j < 20; ++j) {
            if (k & 1) {
                t += a[j];
            }
            k >>= 1;
        }
        b.push_back(t % m);
    }

    sort(b.begin(), b.end());

    int limit2 = 1 << (n / 2);
    for (int i = 0; i < limit2; ++i) {
        long long t = 0;
        int k = i;
        for (int j = 0; j < 20; ++j) {
            if (k & 1) {
                t += a[(n / 2 + n % 2) + j];
            }
            k >>= 1;
        }
        t %= m;

        int idx = (int)std::lower_bound(b.begin(), b.end(), m - t - 1) - b.begin();

        long long t2;
        if (idx < (int)b.size()) {
            t2 = b[idx];
            if (t2 > m - t - 1 && idx - 1 >= 0) {
                t2 = b[idx - 1];
            }
        } else {
            t2 = b.back();
        }

        otv = max(otv, (t + t2) % m);
        if (!b.empty()) {
            otv = max(otv, (t + b.back()) % m);
        }
    }

    cout << otv % m << "\n";

    return 0;
}
